export const COHORT_CARDS = {
 "B2B Executive": ["01","02","03"],
 "Real Estate Professional": ["04","05","06"],
 "Startup Founder": ["07","08","09"],
 "Job Seeker": ["10","11","12"],
 "Consultant or Coach": ["13","14","15"],
 "Thought Leader": ["16","17","18"]
};

export const GENDERED_LOCALES = ["de","fr","es","pt","it"];

// score band -> tier index (low 35-54, mid 55-74, high 75-95)
export function tierIndex(score){ const s = Number(score)||0; return s <= 54 ? 0 : s <= 74 ? 1 : 2; }

// cohort id + score -> card id (e.g. "03"), or null if cohort unknown
export function cardIdFor(cohort, score){
  const ids = COHORT_CARDS[cohort];
  if (!ids) return null;
  return ids[tierIndex(score)];
}
